<?php
if (!defined('ABSPATH')) { exit; }
function emdop6_words($html){$text=trim(preg_replace('/\s+/u',' ',wp_strip_all_tags(strip_shortcodes($html))));if($text==='')return 0;preg_match_all('/[\p{L}\p{M}]+(?:[’\x{27}’-][\p{L}\p{M}]+)*/u',$text,$m);return count($m[0]);}
function emdop6_cat($name,$slug,$en_name,$en_slug,$fallback=''){$term=get_term_by('slug',$slug,'category');if(!$term&&$fallback)$term=get_term_by('name',$fallback,'category');if(!$term)$term=get_term_by('name',$name,'category');if(!$term){$made=wp_insert_term($name,'category',array('slug'=>$slug));if(is_wp_error($made))throw new Exception($made->get_error_message());$term=get_term((int)$made['term_id'],'category');}update_term_meta($term->term_id,'_en_US_name',$en_name);update_term_meta($term->term_id,'_en_US_slug',$en_slug);update_term_meta($term->term_id,'_en_US_published','1');return (int)$term->term_id;}
function emdop6_existing($key,$slug){$ids=get_posts(array('post_type'=>'post','post_status'=>'any','posts_per_page'=>1,'fields'=>'ids','meta_key'=>'_emdo_authority_key','meta_value'=>$key));if($ids)return (int)$ids[0];$p=get_page_by_path($slug,OBJECT,'post');return $p?(int)$p->ID:0;}
$dir=(string)getenv('EMDO_PRIORITY_BATCH06_DIR');if(!$dir||!is_dir($dir))throw new Exception('Priority batch 06 data directory missing');$files=glob(trailingslashit($dir).'*.php');sort($files,SORT_NATURAL);if(count($files)!==5)throw new Exception('Expected five article files');
$guide=emdop6_cat('Guías y consejos','guias-y-consejos','Guides and advice','guides-and-advice');
$cats=array('ham'=>emdop6_cat('Jamones y paletas','jamones-y-paletas','Hams and shoulders','hams-and-shoulders'),'pulses'=>emdop6_cat('Legumbres','legumbres','Pulses','pulses'),'cured'=>emdop6_cat('Embutidos y curados','embutidos-y-curados','Cured meats','cured-meats','Embutidos y curados'),'meat'=>emdop6_cat('Carnes','carnes','Meat','meat'));
$product_slugs=array('ham'=>'jamones-paletas','pulses'=>'legumbres','cured'=>'embutidos-curados','meat'=>'carnes');
$default=(int)get_option('emdo_default_blog_featured_attachment_id',0);if($default<=0||get_post_type($default)!=='attachment')throw new Exception('Central provisional image missing');$default_hash=(string)get_option('emdo_default_blog_featured_hash','');$admins=get_users(array('role'=>'administrator','number'=>1,'fields'=>'ID'));$author=$admins?(int)$admins[0]:1;$rows=array();
foreach($files as $file){$a=require $file;foreach(array('key','priority','slug','en_slug','topic','title','en_title','excerpt','en_excerpt','content','en_content','min_es','min_en') as $f){if(!isset($a[$f])||$a[$f]==='')throw new Exception(basename($file).' missing '.$f);}if(!isset($cats[$a['topic']]))throw new Exception('Unexpected topic '.$a['topic']);if((int)$a['priority']<26||(int)$a['priority']>30)throw new Exception('Unexpected priority '.(int)$a['priority']);$product=$product_slugs[$a['topic']];$content=str_replace('__PRODUCT_CAT__',$product,$a['content']);$en=str_replace('__PRODUCT_CAT__',$product,$a['en_content']);$wes=emdop6_words($content);$wen=emdop6_words($en);if($wes<(int)$a['min_es']||$wen<(int)$a['min_en'])throw new Exception($a['key'].' too short ES='.$wes.'/'.(int)$a['min_es'].' EN='.$wen.'/'.(int)$a['min_en']);$existing=emdop6_existing($a['key'],$a['slug']);$new=$existing<=0;$post=array('post_type'=>'post','post_status'=>'publish','post_author'=>$author,'post_title'=>wp_strip_all_tags($a['title']),'post_name'=>sanitize_title($a['slug']),'post_excerpt'=>wp_strip_all_tags($a['excerpt']),'post_content'=>$content);if($existing)$post['ID']=$existing;$res=$existing?wp_update_post($post,true):wp_insert_post($post,true);if(is_wp_error($res))throw new Exception($a['key'].': '.$res->get_error_message());$id=(int)$res;wp_set_post_categories($id,array($guide,$cats[$a['topic']]),false);update_post_meta($id,'_emdo_authority_key',$a['key']);update_post_meta($id,'_emdo_priority_plan','38');update_post_meta($id,'_emdo_priority_order',(string)$a['priority']);update_post_meta($id,'_emdo_priority_batch','6');update_post_meta($id,'_en_US_post_title',wp_strip_all_tags($a['en_title']));update_post_meta($id,'_en_US_post_name',sanitize_title($a['en_slug']));update_post_meta($id,'_en_US_post_excerpt',wp_strip_all_tags($a['en_excerpt']));update_post_meta($id,'_en_US_post_content',$en);update_post_meta($id,'_en_US_ready','1');update_post_meta($id,'_en_US_published','1');update_post_meta($id,'_emdo_editorial_updated',gmdate('c'));$current=(int)get_post_thumbnail_id($id);$marked=(string)get_post_meta($id,'_emdo_uses_default_featured',true)==='1';if($new||$marked||$current<=0){update_post_meta($id,'_thumbnail_id',$default);update_post_meta($id,'_emdo_uses_default_featured','1');update_post_meta($id,'_emdo_editorial_image_approved_id',$default);update_post_meta($id,'_emdo_editorial_cover_asset_id','emdo-blog-default-featured');update_post_meta($id,'_emdo_editorial_cover_brand_safe','1');update_post_meta($id,'_emdo_default_featured_hash',$default_hash);}clean_post_cache($id);$rows[]=array('key'=>$a['key'],'priority'=>(int)$a['priority'],'id'=>$id,'status'=>get_post_status($id),'slug'=>get_post_field('post_name',$id),'en_slug'=>sanitize_title($a['en_slug']),'thumbnail_id'=>(int)get_post_thumbnail_id($id),'provisional'=>(string)get_post_meta($id,'_emdo_uses_default_featured',true),'words_es'=>$wes,'words_en'=>$wen,'min_es'=>(int)$a['min_es'],'min_en'=>(int)$a['min_en'],'topic'=>$a['topic'],'product_category'=>$product,'has_products_es'=>strpos($content,'[products')!==false,'has_products_en'=>strpos($en,'[products')!==false);}
usort($rows,function($a,$b){return $a['priority']<=>$b['priority'];});echo wp_json_encode(array('batch'=>'priority-06','default'=>$default,'posts'=>$rows),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT).PHP_EOL;